@Entity()
export class Order { @PrimaryGeneratedColumn() id!: number; @Column() due!: Date; }

export class OrderService {
  constructor(private readonly db: DataSource) {}          // injected

  overdue(on: Date): Promise<Order[]> {
    return this.db.getRepository(Order).find({            // collection-like and typed
      where: { due: LessThan(on) },
      order: { due: "ASC" },
    });
  }
}

