import { PrismaClient } from "@prisma/client";
const prisma = new PrismaClient();

export async function findOverdueOrders(on: Date): Promise<Order[]> {
  return prisma.order.findMany({                    // typed, no hand-written SQL
    where: { due: { lt: on } },
    orderBy: { due: "asc" },
  });
}
